import{_ as e,o,c as n,a2 as s}from"./chunks/framework.CQxpk36T.js";const p=JSON.parse('{"title":"Connecting to Home Assistant","description":"","frontmatter":{},"headers":[],"relativePath":"en/home-assistant/index.md","filePath":"en/home-assistant/index.md","lastUpdated":1793574169000}'),a={name:"en/home-assistant/index.md"};function i(r,t,c,d,h,l){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="connecting-to-home-assistant" tabindex="-1">Connecting to Home Assistant <a class="header-anchor" href="#connecting-to-home-assistant" aria-label="Permalink to &quot;Connecting to Home Assistant&quot;">​</a></h1><p>HAven talks to Home Assistant directly, from the browser, over the same WebSocket connection as Home Assistant&#39;s own interface. No integration to install, no token to copy.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><ol><li>Open the <strong>settings</strong> (the badge at the top right).</li><li>Enter the <strong>Home Assistant address</strong> (Adresse de Home Assistant), for example <code>http://homeassistant.local:8123</code>.</li><li><strong>Se connecter</strong> (connect): Home Assistant&#39;s usual login page opens. Log in; you come back to HAven, which receives live states.</li></ol><p>The badge switches to <strong>Home Assistant</strong>. The connection is kept in the browser: later visits reconnect by themselves. <strong>Se déconnecter</strong> (disconnect) forgets it and goes back to demo mode.</p><div class="tip custom-block"><p class="custom-block-title">An account for the model</p><p>For a wall tablet or a shared phone, create a dedicated account in Home Assistant (Settings → People → Add person, with login allowed) and connect HAven with it.</p></div><h2 id="what-haven-reads" tabindex="-1">What HAven reads <a class="header-anchor" href="#what-haven-reads" aria-label="Permalink to &quot;What HAven reads&quot;">​</a></h2><ul><li>the <strong>states</strong> of every entity, live;</li><li><strong>Areas</strong>, <strong>devices</strong> and <strong>entities</strong> (to know which entity is in which room); HAven follows their changes without reloading;</li><li>the day&#39;s <strong>history</strong> of the energy sensors (Énergie tab).</li></ul><p>And what it sends: only the <strong>actions</strong> you trigger (turn on, set a target temperature, open a door…). HAven automates nothing and doesn&#39;t change Home Assistant&#39;s configuration.</p><h2 id="a-connection-that-holds" tabindex="-1">A connection that holds <a class="header-anchor" href="#a-connection-that-holds" aria-label="Permalink to &quot;A connection that holds&quot;">​</a></h2><p>On a phone, the browser cuts the connections of background pages. When you come back to HAven (app reopened, page visible again, network back), the connection is checked and re-established at once if it had dropped: states are fresh at first glance.</p><p>Until a device has confirmed a command, its switch or drawing <strong>pulses</strong> gently; if nothing comes back after a few seconds, it returns to its real state.</p><h2 id="http-or-https" tabindex="-1">HTTP or HTTPS <a class="header-anchor" href="#http-or-https" aria-label="Permalink to &quot;HTTP or HTTPS&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">No mixing</p><p>If HAven is served over <strong>HTTPS</strong>, Home Assistant must be too: browsers refuse to let a secure page talk to an HTTP address.</p></div><table tabindex="0"><thead><tr><th>HAven</th><th>Home Assistant</th><th></th></tr></thead><tbody><tr><td><code>http://…</code></td><td><code>http://…</code> or <code>https://…</code></td><td>✅</td></tr><tr><td><code>https://…</code></td><td><code>https://…</code></td><td>✅</td></tr><tr><td><code>https://…</code></td><td><code>http://…</code></td><td>❌ blocked by the browser</td></tr></tbody></table><p>On a private network (Tailscale for example), the simplest is to serve both the same way. See <a href="/HAven-docs/en/hebergement">Hosting</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/HAven-docs/en/home-assistant/correspondances">What is shown and controlled</a>: what each entity becomes in the model.</li><li><a href="/HAven-docs/en/guide/pieces">Rooms and Areas</a>: linking the model&#39;s rooms to Areas.</li></ul>',18)])])}const m=e(a,[["render",i]]);export{p as __pageData,m as default};
